contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 loanID, address to) public payable {
        require(to != address(0), "zero to");

        // Need an existing loan whose lender is this test contract (msg.sender for calls on c).
        // Clear a request to create a loan; msg.sender becomes the lender.
        uint256 amount = 1;
        uint256 interest = 0;
        uint256 loanToCollateral = 1;
        uint256 duration = 1;
        c.requestLoan(amount, interest, loanToCollateral, duration);

        bool cleared;
        try c.clearRequest(0, false, false) returns (uint256 createdID) {
            cleared = (createdID == 0);
        } catch {
            cleared = false;
        }
        require(cleared, "clearRequest did not create loan 0");

        // Only the lender of the loan can call approveTransfer; this test contract is the lender.
        // Use loanID 0, which we just created, regardless of the input loanID parameter.
        bool ok;
        try c.approveTransfer(to, 0) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 approvalsValue = (to == address(0)) ? 0 : uint160(to);
        assert(ok && c.approvals(0) == approvalsValue);
    }

    receive() external payable {}
}

