contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 reqID_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral zero");
        require(c.owner() == address(this), "owner not test contract");

        uint256 preLen = c.requests.length;

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        bool created = c.isActive(reqID_);

        bool reverted;
        try c.rescindRequest(reqID_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterActive = c.isActive(reqID_);

        if (reqID_ < c.requests.length) {
            assert(!reverted == (created && reqID_ < preLen + 1 && afterActive == false));
        }
    }

    receive() external payable {}
}

