contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, uint256 repaid_) public payable {
        require(loanToCollateral_ > 0, "zero ltc");
        require(duration_ > 0, "zero duration");
        require(amount_ > 0, "zero amount");

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_);
        uint256 loanID = c.clearRequest(0, false, false);

        C.Loan memory beforeLoan = c.getLoan(loanID);
        require(beforeLoan.amount > 0, "empty loan");
        require(beforeLoan.collateral > 0, "no collateral");

        uint256 capped = repaid_ > beforeLoan.amount ? beforeLoan.amount : repaid_;
        uint256 expected = (beforeLoan.collateral * capped) / beforeLoan.amount;
        if (expected == 0) return;

        uint256 decollateralized = c.repayLoan(loanID, repaid_);

        assert(decollateralized == expected);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount_, uint256 loanToCollateral_, uint256 duration_, uint256 repaid_) public payable {
        require(amount_ > 0, "amount zero");
        require(amount_ <= 1e18, "amount too big");
        require(loanToCollateral_ > 0, "ltc zero");
        require(loanToCollateral_ <= 1e18, "ltc too big");
        require(duration_ > 0, "duration zero");
        require(duration_ <= 365 days, "duration too big");
        require(repaid_ > 0, "repaid zero");
        require(repaid_ <= 1e18, "repaid too big");

        c.requestLoan(amount_, 0, loanToCollateral_, duration_);
        uint256 loanID = c.clearRequest(0, false, false);

        uint256 loanAmount = c.getLoan(loanID).amount;
        uint256 loanCollateral = c.getLoan(loanID).collateral;

        uint256 capped = repaid_ > loanAmount ? loanAmount : repaid_;
        uint256 expected = (loanCollateral * capped) / loanAmount;
        require(expected > 0, "decollateralized zero");

        uint256 returned = c.repayLoan(loanID, repaid_);

        assert(returned == expected);
    }

    receive() external payable {}
}

