contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLoanToCollateral,
        uint256 reqDuration,
        uint256 repaid
    ) public {
        require(reqAmount > 0);
        require(reqLoanToCollateral > 0);
        require(reqDuration > 0);
        require(reqInterest <= 1e18);
        require(reqAmount >= reqLoanToCollateral || (reqAmount * (10 ** 18)) / reqLoanToCollateral > 0);

        uint256 reqID = c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration);
        uint256 loanID = c.clearRequest(reqID, false, false);

        C.Loan memory loanBefore = c.getLoan(loanID);
        uint256 expiry = loanBefore.expiry;
        uint256 collateralBefore = loanBefore.collateral;

        bool reverted;
        uint256 returned;
        try c.repayLoan(loanID, repaid) returns (uint256 r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (block.timestamp > expiry) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(returned > 0 && returned <= collateralBefore);
        }
    }
}

