contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLTC,
        uint256 reqDuration,
        bool repayDirect,
        bool isCallback,
        uint256 loanID,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_
    ) public {
        require(reqInterest <= 1e18, "interest too high");
        require(reqDuration <= 3650 days, "duration too long");

        c.requestLoan(reqAmount, reqInterest, reqLTC, reqDuration);

        uint256 loanBefore;
        try c.clearRequest(0, repayDirect, isCallback) returns (uint256 id) {
            loanBefore = id;
        } catch {
            loanBefore = type(uint256).max;
        }
        require(loanBefore != type(uint256).max, "clear failed");

        C.Loan memory l = c.getLoan(loanID);

        uint256 oldAmount = l.amount;
        uint256 oldCollateral = l.collateral;
        uint256 oldExpiry = l.expiry;

        bool reverted;
        try c.provideNewTermsForRoll(loanID, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        C.Loan memory l2 = c.getLoan(loanID);

        address caller = address(this);
        bool callerIsLender = (caller == l.lender);

        if (!reverted) {
            assert(callerIsLender);
        }

        if (callerIsLender && !reverted) {
            assert(l2.amount == l.amount);
            assert(l2.collateral == l.collateral);
            assert(l2.expiry == l.expiry);
        }

        if (!callerIsLender && !reverted) {
            assert(l2.amount == oldAmount);
            assert(l2.collateral == oldCollateral);
            assert(l2.expiry == oldExpiry);
        }

        if (reverted) {
            assert(l2.amount == oldAmount);
            assert(l2.collateral == oldCollateral);
            assert(l2.expiry == oldExpiry);
        }
    }
}

